function renderGame() {
  background(10, 30, 60);

  push();
  translate(-width / 2, -height / 2, 0);

  ambientLight(40, 80, 120);
  directionalLight(200, 240, 255, 0.5, 1, -0.5);
  pointLight(0, 255, 255, player.x, player.y, 100);

  // Ocean Floor
  push();
  translate(width / 2, height, -20);
  fill(160, 140, 100);
  ambientMaterial(160, 140, 100);
  box(width * 1.5, 40, 100);
  pop();

  // Surface Layer
  push();
  fill(0, 120, 200);
  ambientMaterial(0, 120, 200);
  translate(width / 2, 35, -10);
  box(width * 1.5, 70, 40);
  pop();

  // Seaweed
  fill(34, 139, 34);
  ambientMaterial(34, 139, 34);
  for (let sw of seaweeds) {
    push();
    translate(sw.x, sw.y - sw.h / 2, -10);
    rotateZ(Math.sin(tick * 0.05 + sw.swayOffset) * 0.1);
    cylinder(sw.w, sw.h);
    pop();
  }

  // Background Fishes
  for (let f of bgFishes) {
    push();
    translate(f.x, f.y, f.z);
    let dir = f.vx > 0 ? 0 : PI;
    rotateY(dir);
    fill(f.color[0], f.color[1], f.color[2]);
    ambientMaterial(f.color[0], f.color[1], f.color[2]);
    ellipsoid(8, 4, 2);
    translate(-6, 0, 0);
    box(2, 6, 1);
    pop();
  }

  // Bubbles
  fill(180, 220, 255);
  ambientMaterial(180, 220, 255);
  for (let b of bubbles) {
    push();
    translate(b.x + Math.sin(tick * 0.05 + b.seed) * 5, b.y, b.z);
    sphere(b.r);
    pop();
  }

  // Oxygen Bar Background
  push();
  fill(20);
  ambientMaterial(20);
  translate(width / 2, height - 10, 5);
  box(width - 20, 10, 5);
  pop();

  // Oxygen Bar Fill
  let oxW = Math.max(0, (player.oxygen / 100) * (width - 20));
  push();
  fill(0, 255, 255);
  ambientMaterial(0, 255, 255);
  translate(10 + oxW / 2, height - 10, 6);
  box(oxW, 8, 6);
  pop();

  // Collected Divers Indicators
  fill(255, 100, 0);
  ambientMaterial(255, 100, 0);
  for (let i = 0; i < player.diverCount; i++) {
    push();
    translate(20 + i * 15, 20, 5);
    sphere(4);
    pop();
  }

  // Divers
  for (let d of divers) {
    push();
    translate(d.x, d.y, 0);
    let dDir = d.vx > 0 ? 1 : -1;
    rotateY(dDir === 1 ? 0 : PI);

    fill(255, 100, 0);
    ambientMaterial(255, 100, 0);

    // Body
    push();
    rotateZ(HALF_PI);
    cylinder(d.h / 2.5, d.w - 4);
    pop();

    // Head
    push();
    translate(d.w / 2, 0, 0);
    fill(255, 200, 150);
    ambientMaterial(255, 200, 150);
    sphere(d.h / 2.5);
    pop();

    // Flippers
    push();
    fill(20);
    ambientMaterial(20);
    translate(-d.w / 2, -2, 0);
    box(4, 2, 6);
    translate(0, 4, 0);
    box(4, 2, 6);
    pop();
    pop();
  }

  // Enemies
  for (let e of enemies) {
    push();
    translate(e.x, e.y, 0);
    let dir = e.vx > 0 ? 1 : -1;
    rotateY(dir === 1 ? 0 : PI);

    if (e.type === 'sub') {
      fill(220, 50, 50);
      specularMaterial(220, 50, 50);
      shininess(30);

      // Body
      push();
      rotateZ(HALF_PI);
      cylinder(e.h / 2, e.w - 6);
      pop();

      // Front dome
      push();
      translate((e.w / 2 - 3), 0, 0);
      sphere(e.h / 2);
      pop();

      // Back cone
      push();
      translate(-(e.w / 2 - 3), 0, 0);
      rotateZ(-HALF_PI);
      cone(e.h / 2, 6);
      pop();

      // Periscope
      push();
      translate(0, -e.h / 2 - 2, 0);
      box(2, 4, 2);
      pop();
    } else {
      fill(100, 130, 160);
      specularMaterial(100, 130, 160);
      shininess(10);

      // Body
      ellipsoid(e.w / 2, e.h / 2, e.h / 2);

      // Dorsal Fin
      push();
      translate(-2, -e.h / 2, 0);
      cone(e.h / 3, e.h);
      pop();

      // Tail Fin
      push();
      translate(-e.w / 2 - 2, 0, 0);
      box(4, e.h * 1.5, 2);
      pop();
    }
    pop();
  }

  // Player Bullets
  fill(255, 255, 0);
  ambientMaterial(255, 255, 0);
  for (let b of pBullets) {
    push();
    translate(b.x, b.y, 0);
    rotateZ(HALF_PI);
    cylinder(2, 6);
    pop();
  }

  // Enemy Bullets
  fill(255, 100, 0);
  ambientMaterial(255, 100, 0);
  for (let b of eBullets) {
    push();
    translate(b.x, b.y, 0);
    rotateZ(HALF_PI);
    cylinder(2, 6);
    pop();
  }

  // Player
  if (gameState === 'PLAYING') {
    push();
    translate(player.x, player.y, 0);
    rotateY(player.facing === 1 ? 0 : PI);

    fill(255, 220, 0);
    specularMaterial(255, 220, 0);
    shininess(40);

    // Body
    push();
    rotateZ(HALF_PI);
    cylinder(player.h / 2, player.w - 8);
    pop();

    // Front dome
    push();
    translate((player.w / 2 - 4), 0, 0);
    sphere(player.h / 2);
    pop();

    // Back cone
    push();
    translate(-(player.w / 2 - 4), 0, 0);
    rotateZ(-HALF_PI);
    cone(player.h / 2, 8);
    pop();

    // Periscope
    push();
    translate(0, -player.h / 2 - 2, 0);
    box(2, 4, 2);
    translate(2, -2, 0);
    box(4, 2, 2);
    pop();

    pop();
  }

  pop();
}
